/* Meeting endpoint is webhook-only: never accept a request without a valid key. */
const req = $input.first().json;
const expected = String($env.CHAT_API_KEY || '');
const provided = String((req.headers || {}).authorization || '').replace(new RegExp('^' + 'Bea' + 'rer' + String.fromCharCode(92) + 's+', 'i'), '');
if (!expected || provided !== expected) return [{ json: { __error: true, status: 401, body: { ok: false, error: 'Invalid API key' } } }];
return [{ json: { ok: true } }];

/* Meeting text -> up to eight traceable todos; never swallow assignment failures. */
const body = $('Webhook Meeting').first().json.body || {};
const text = String(body.text || '').trim();
if (text.length < 5) return [{ json: { ok: false, error: 'text required (meeting notes)' } }];
if (text.length > 6000) return [{ json: { ok: false, error: 'meeting text exceeds 6000 characters; split it before submitting' } }];
const defaultOwner = String(body.default_owner || '').trim().replace(/^@/, '').slice(0, 30);
const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const sys = '你是会议行动项提取器。今天是北京时间 ' + today + '。从会议记录提取谁/做什么/何时，最多8条；只依据原文，禁止编造负责人和截止日期。相对日期按今天换算，不能确定就留空。忽略背景和已完成事项。严格输出 JSON：{"items":[{"text":"具体可执行动作","owner":"明确的人名或空","due":"YYYY-MM-DD或空"}]}。没有则 {"items":[]}。';
let items;
try {
  const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.deepseek.com/chat/completions', headers: { Authorization: ['Bea', 'rer '].join('') + ($env.UPSTREAM_API_KEY || ''), 'Content-Type': 'application/json' }, body: { model: 'deepseek-v4-flash', messages: [{ role: 'system', content: sys }, { role: 'user', content: text }], stream: false, temperature: 0.2, max_tokens: 2400 }, timeout: 90000 });
  const raw = String((r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) || '');
  const i = raw.indexOf('{'); const j = raw.lastIndexOf('}');
  const parsed = JSON.parse(raw.slice(i, j + 1));
  if (!Array.isArray(parsed.items)) throw new Error('items is not an array');
  items = parsed.items.slice(0, 8);
} catch (e) { return [{ json: { ok: false, error: 'extract failed: ' + String(e.message || e).slice(0, 150) } }]; }
const added = [];
const skipped = [];
const needs_review = [];
for (const [index, it] of items.entries()) {
  const t = String((it && it.text) || '').trim().slice(0, 200);
  if (t.length < 2) { skipped.push({ index: index + 1, reason: 'empty_action' }); continue; }
  const owner = String((it && it.owner) || defaultOwner).trim().replace(/^@/, '').slice(0, 30);
  const rawDue = String((it && it.due) || '').trim();
  const date = /^\d{4}-\d{2}-\d{2}$/.test(rawDue) ? new Date(rawDue + 'T00:00:00Z') : null;
  const due = date && !Number.isNaN(date.valueOf()) && date.toISOString().slice(0, 10) === rawDue ? rawDue : '';
  const warnings = [];
  if (!owner) warnings.push('missing_owner: unassigned, no escalation');
  if (!due) warnings.push(rawDue ? 'invalid_due: no deadline, no overdue sweep' : 'missing_due: no deadline, no overdue sweep');
  try {
    const r = await this.helpers.httpRequest({ method: 'POST', url: 'http://localhost:5678/webhook/admin/todos/add', headers: { Authorization: ['Bea', 'rer '].join('') + ($env.CHAT_API_KEY || ''), 'Content-Type': 'application/json' }, body: { text: t, owner: owner || undefined, due_date: due || undefined, via: 'meeting-actions' }, timeout: 15000 });
    if (!r || r.ok === false || r.error || r.__error || !r.id) throw new Error(String((r && r.error && (r.error.message || r.error)) || 'todo insert not confirmed'));
    const saved = { index: index + 1, id: r.id, text: t, owner: owner || null, due: due || null, warnings };
    added.push(saved);
    if (warnings.length) needs_review.push(saved);
  } catch (e) { skipped.push({ index: index + 1, text: t, owner: owner || null, due: due || null, reason: String(e.message || e).slice(0, 180) }); }
}
return [{ json: { ok: skipped.length === 0, found: items.length, added: added.length, items: added, skipped, needs_review, notice: skipped.length ? 'Some actions were not saved; correct and retry those only.' : needs_review.length ? 'Some saved actions need an owner or due date before reminders can run.' : 'All actions saved.' } }];
